{
  "events": [
    {
      "id": "E1",
      "title": "珀莱雅举办2026创新科技大会（PSTC 2026），发布《中国系统性护肤研究与产业实践白皮书》及红宝石面霜4.0、源力精华4.0升级产品",
      "date": "2026-08-25",
      "category": "research",
      "sourceIds": ["C1"],
      "quote": "8月25日，以\"科技向新，为美前行\"为主题的珀莱雅2026创新科技大会（PSTC 2026 — PROYA FORWARD）在上海举行。",
      "summary": "珀莱雅于2026年8月25日召开PSTC 2026大会，联合上海日用化学品行业协会发布《中国系统性护肤研究与产业实践白皮书》，提出CRMVP五维循证研究模型；同步推出红宝石面霜4.0与源力精华4.0两大升级产品，并发布全新品牌VI系统。大会明确‘构建专研中国人肌肤的科学护肤体系’方向，强调从实验室到真实场景的系统性验证路径。"
    },
    {
      "id": "E2",
      "title": "珀莱雅在PSTC 2026大会上宣布启动‘PSTC’科技传播IP，推动科技叙事由单点成果转向系统能力呈现",
      "date": "2026-08-25",
      "category": "research",
      "sourceIds": ["C1"],
      "quote": "并正式启动\"PSTC\"科技传播IP，推动品牌科技传播由单点成果表达走向系统科研能力呈现。",
      "summary": "PSTC 2026大会正式确立‘PSTC’作为长期科技传播IP，旨在将珀莱雅科技能力从分散的产品技术点状宣传，升级为涵盖行业趋势、品牌焕新、科学发布、科研转化、实证共创的系统性能力叙事。"
    },
    {
      "id": "E3",
      "title": "珀莱雅新款修颜防晒乳完成国家药监局备案并开展终端销售，含微粒化氧化锌与乙基己基三嗪酮双通路防护体系",
      "date": "2026-10-22",
      "category": "product",
      "sourceIds": ["C3"],
      "quote": "所有产品均经国家药监局备案，不含华熙生物旗下任何成分及品牌，全部为终端在售2026年春季批次。",
      "summary": "珀莱雅新款修颜防晒乳作为2026年春季批次新品已通过国家药监局备案并在终端渠道销售，采用微粒化氧化锌（80–120nm）与乙基己基三嗪酮组合的物理/物化结合型防晒体系，同步添加烟酰胺与云母微珠实现修色功效，配套赠品为80ml海洋水活精华水。"
    }
  ],
  "judgments": [
    {
      "title": "PSTC 2026科技大会与财报中‘研发费用率微降至1.85%’存在表里张力",
      "text": "财报显示研发费用率同比下降，但PSTC大会高调披露332项授权专利及22项国家标准参与制定，提示研发投入可能更多体现为标准制定、产学研协同等非费用化形态；若母公司研发费用率达4.32%，则集团内部分工或导致费用归集口径与成果产出不完全对应，仍需验证研发资源在母子公司间的实际配置逻辑。",
      "financialEvidenceIds": ["P10", "P23"],
      "sourceIds": ["C1", "C2"]
    },
    {
      "title": "修颜防晒乳实测数据优异但未反映于上半年收入结构",
      "text": "C3测评中珀莱雅修颜防晒乳在UVA稳定性、防水持效性、修色即时性三项指标居首，且为唯一实现‘防晒+修色+舒缓’三重备案功效宣称的产品，但财报中护肤类收入同比下降6.87%，提示该新品尚未形成规模贡献；其作为2026年春季批次产品，销售起量或集中于下半年，若Q3-Q4渠道铺货与消费者教育未达预期，则难以扭转护肤基本盘承压态势。",
      "financialEvidenceIds": ["P10"],
      "sourceIds": ["C3"]
    }
  ],
  "actions": [
    {
      "audience": "原料商",
      "text": "建议评估微粒化氧化锌（80–120nm）、云母微珠、乙基己基三嗪酮等修颜防晒乳核心成分的供应稳定性与合规备案支持能力。",
      "financialEvidenceIds": ["P10"],
      "sourceIds": ["C3"],
      "verifyWith": "需核对自身氧化锌纳米级分散工艺稳定性、云母微珠粒径控制精度、乙基己基三嗪酮进口注册资质及国内备案配合文件"
    },
    {
      "audience": "代工厂",
      "text": "建议确认是否具备SPF50+ PA++++级物理/物化结合型防晒乳的配方开发、防水持效性验证及三重功效（防晒/修色/舒缓）协同备案支持能力。",
      "financialEvidenceIds": ["P10"],
      "sourceIds": ["C3"],
      "verifyWith": "需准备防晒剂光稳定性全周期检测报告、人体斑贴试验合作机构资源、国家药监局功效宣称备案技术文档及过往同类产品ODM案例"
    },
    {
      "audience": "品牌方",
      "text": "建议审慎评估将‘系统性护肤’叙事转化为终端复购的可行性，避免过度依赖白皮书与专利数量等非直接消费触点。",
      "financialEvidenceIds": ["P10", "P23"],
      "sourceIds": ["C1", "C2"],
      "verifyWith": "需验证CRMVP五维模型在消费者调研中的心智渗透率、红宝石/源力系列4.0版本在618后三个月的复购率及退货率数据"
    }
  ]
}
